package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import com.tencent.weknora.task.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.config.AutowireCapableBeanFactory;

/** Shared-owner production upload, native fanout/classifier HTTP and single pooled connection. */
@org.springframework.boot.test.context.SpringBootTest(properties={"weknora.jwt-secret=isolated-native-pipeline-trace-secret","weknora.bridge.enabled=false","weknora.knowledge.processing.enabled=true","weknora.knowledge.upload.enabled=true","weknora.tasks.enabled=true","weknora.tasks.poll-millis=3600000","weknora.retrieve-driver=sqlite","SSRF_WHITELIST=127.0.0.1","SSRF_DNS_WHITELIST_ONLY=true","logging.level.root=WARN","debug=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class KnowledgeAutoTagPipelineHttpIntegrationTest {
  @org.springframework.test.context.DynamicPropertySource static void properties(org.springframework.test.context.DynamicPropertyRegistry p){KnowledgeProcessingSpanPipelineHttpIntegrationTest.properties(p);}
  @Autowired AutowireCapableBeanFactory beans;@Autowired KnowledgeAutoTagHandler autoTag;
  final KnowledgeProcessingSpanPipelineHttpIntegrationTest f=new KnowledgeProcessingSpanPipelineHttpIntegrationTest();
  final ObjectMapper json=new ObjectMapper();final AtomicInteger chats=new AtomicInteger();HttpServer server;Runnable during=()->{};
  @BeforeEach void setup()throws Exception{
    beans.autowireBean(f);f.setup();f.jdbc.update("UPDATE knowledge_bases SET question_generation_config='{}',auto_tag_config=? WHERE id='trace-kb'","{\"enabled\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8));
    f.jdbc.update("INSERT INTO knowledge_tags(id,tenant_id,knowledge_base_id,name,sort_order,seq_id,created_at) VALUES('trace-auto-tag',8,'trace-kb','Delivery',0,70001,'2026-01-01') ON CONFLICT(id) DO NOTHING");
    server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/",exchange->{try{JsonNode body=json.readTree(exchange.getRequestBody());ObjectNode response;if(exchange.getRequestURI().getPath().endsWith("chat/completions")){chats.incrementAndGet();during.run();response=json.createObjectNode().set("choices",json.createArrayNode().add(json.createObjectNode().put("finish_reason","stop").set("message",json.createObjectNode().put("role","assistant").put("content","{\"matches\":[{\"index\":1}]}"))));}else{var data=json.createArrayNode();for(int i=0;i<body.path("input").size();i++)data.add(json.createObjectNode().put("index",i).set("embedding",json.createArrayNode().add(1).add(0).add(0)));response=json.createObjectNode().set("data",data);}byte[] bytes=json.writeValueAsBytes(response);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}finally{exchange.close();}});server.start();var p=json.createObjectNode().put("provider","generic").put("base_url","http://127.0.0.1:"+server.getAddress().getPort()+"/v1");p.set("embedding_parameters",json.createObjectNode().put("dimension",3));f.jdbc.update("UPDATE models SET parameters=? WHERE id='trace-embedding'",p.toString());f.jdbc.update("INSERT INTO models(id,tenant_id,name,type,source,parameters,is_builtin,status) VALUES('trace-auto-model',8,'unknown','KnowledgeQA','remote',?,false,'active') ON CONFLICT(id) DO UPDATE SET parameters=excluded.parameters",p.toString());f.jdbc.update("UPDATE knowledge_bases SET summary_model_id='trace-auto-model' WHERE id='trace-kb'");
  }
  @AfterEach void cleanup(){if(server!=null)server.stop(0);f.jdbc.update("UPDATE knowledge_bases SET auto_tag_config='{}',question_generation_config='{}',summary_model_id='' WHERE id='trace-kb'");f.jdbc.update("DELETE FROM knowledge_tag_relations WHERE tag_id='trace-auto-tag'");f.jdbc.update("DELETE FROM knowledge_tags WHERE id='trace-auto-tag'");}
  record Flow(String id,TaskRecord post){}
  Flow prepared(boolean summary)throws Exception{String id=f.upload("Delivery release policy documents the access and review checkpoints. "+UUID.randomUUID());if(summary)f.jdbc.update("UPDATE knowledges SET metadata=? WHERE id=?",json.createObjectNode().set("process_overrides",json.createObjectNode().put("summary_enabled",true)).toString(),id);var document=f.claim("default");f.document.execute(document,f.cancellation(document));f.tasks.complete(document,json.createObjectNode());return new Flow(id,f.claim("postprocess"));}
  JsonNode dispatch(Flow flow)throws Exception{var out=f.postprocess.execute(flow.post(),f.cancellation(flow.post()));f.tasks.complete(flow.post(),json.createObjectNode());return out;}
  TaskRecord tag(String id){var ids=f.jdbc.queryForList("SELECT id FROM java_task_jobs WHERE type='knowledge:auto_tag' AND json_extract(payload,'$.knowledge_id')=? AND status='pending'",String.class,id);assertEquals(1,ids.size());f.jdbc.update("UPDATE java_task_jobs SET available_at=0 WHERE id=?",ids.getFirst());return f.claim("summary");}
  int tags(String id){return f.jdbc.queryForObject("SELECT COUNT(*) FROM knowledge_tag_relations WHERE knowledge_id=?",Integer.class,id);}
  int pending(String id){return f.jdbc.queryForObject("SELECT pending_subtasks_count FROM knowledges WHERE id=?",Integer.class,id);}
  @Test void sharedUploadFinishesParsingBeforeAutoTagAndKeepsActorAndIndexes()throws Exception{
    var flow=prepared(false);assertTrue(dispatch(flow).path("enqueued_auto_tag").asBoolean());assertEquals("completed",f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,flow.id()));assertEquals(0,pending(flow.id()));var job=tag(flow.id());assertEquals("knowledge:auto_tag",job.type());assertEquals(8,job.tenantId());assertEquals(3,job.maxAttempts());assertEquals(120000,job.timeoutMillis());assertEquals(1,autoTag.execute(job,f.cancellation(job)).path("added_tag_count").asInt());f.tasks.complete(job,json.createObjectNode());assertEquals(1,tags(flow.id()));assertEquals(1,chats.get());assertEquals(0,pending(flow.id()));assertTrue(f.count("lite_embeddings",flow.id())>0);assertEquals("done",f.node(f.get(flow.id(),"spans",f.callerToken,200).path("trace"),"postprocess.auto_tag").path("status").asText());f.get(flow.id(),"spans",f.foreignToken,403);
  }
  @Test void autoTagDoesNotDrainPendingSummarySlot()throws Exception{var flow=prepared(true);assertTrue(dispatch(flow).path("enqueued_summary").asBoolean());assertEquals(1,pending(flow.id()));var job=tag(flow.id());autoTag.execute(job,f.cancellation(job));f.tasks.complete(job,json.createObjectNode());assertEquals(1,pending(flow.id()));assertEquals("finalizing",f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,flow.id()));assertEquals(1,tags(flow.id()));}
  @Test void lostLeaseDuringChatNeverWritesTagsOrCounters()throws Exception{var flow=prepared(true);dispatch(flow);var job=tag(flow.id());during=()->f.jdbc.update("UPDATE java_task_jobs SET lease_owner='successor' WHERE id=?",job.id());assertThrows(CancellationException.class,()->autoTag.execute(job,f.cancellation(job)));assertEquals(0,tags(flow.id()));assertEquals(1,pending(flow.id()));}
  @Test void supersededProviderResultNeverClassifiesTheNewAttempt()throws Exception{var flow=prepared(true);dispatch(flow);var job=tag(flow.id());during=()->{f.tracker.open(8,flow.id(),"successor");f.jdbc.update("UPDATE knowledges SET pending_subtasks_count=2 WHERE id=?",flow.id());};assertEquals("attempt_superseded",autoTag.execute(job,f.cancellation(job)).path("skipped").asText());assertEquals(0,tags(flow.id()));assertEquals(2,pending(flow.id()));}
  @Test void duplicateDeliveryPreservesManualTagsAndAvoidsSecondModelCall()throws Exception{var flow=prepared(false);dispatch(flow);var job=tag(flow.id());autoTag.execute(job,f.cancellation(job));assertEquals("knowledge_already_tagged",autoTag.execute(job,f.cancellation(job)).path("skipped").asText());assertEquals(1,chats.get());assertEquals(1,tags(flow.id()));assertEquals(0,pending(flow.id()));}
  @Test void realCancelDuringClassifierRetainsIndexesAndRejectsTagAttachment()throws Exception{var flow=prepared(true);dispatch(flow);var job=tag(flow.id());long indexes=f.count("lite_embeddings",flow.id());during=()->{try{var response=f.mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/knowledge/"+flow.id()+"/cancel-parse").header("Authorization","Bearer "+f.callerToken)).andReturn().getResponse();assertEquals(200,response.getStatus());}catch(Exception e){throw new RuntimeException(e);}};assertThrows(IllegalStateException.class,()->autoTag.execute(job,f.cancellation(job)));assertEquals(0,tags(flow.id()));assertEquals(0,pending(flow.id()));assertEquals(indexes,f.count("lite_embeddings",flow.id()));assertEquals("cancelled",f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,flow.id()));}
}
